command:
set -euo pipefail; env_file="${UA_WHATBOX_ENV_FILE:-${XDG_CONFIG_HOME:-$HOME/.config}/upload-assistant/whatbox.env}"; set -a; source "$env_file"; set +a; export SSHPASS="$UA_WHATBOX_PASSWORD"; sshpass -e ssh -4 -o PubkeyAuthentication=no -o PreferredAuthentications=password -o StrictHostKeyChecking=yes artemisprime@destiny.whatbox.ca bash -s <<'REMOTE'
set -u
echo container-processes:
podman exec upload-assistant-wastaken ps -eo pid,ppid,user,comm,args 2>&1 || true
echo container-sockets:
podman exec upload-assistant-wastaken sh -c 'command -v ss >/dev/null && ss -ltnp || (command -v netstat >/dev/null && netstat -ltnp || true)' 2>&1 || true
echo parent-children:
podman inspect upload-assistant-wastaken --format '{{.State.Pid}}'
REMOTE
